1	// 念念 · 陈列室 —— 核心数据模型（B1 地基）
2	//
3	// 关系：Scene 与 Item 多对多，经 Placement 关联。
4	// 一件 Item 可被摆进多个 Scene（每次摆放是一条 Placement），
5	// 同一 Scene 里也可摆多件 Item。
6	// 「故事」挂在 Item 本身（跨场景同步），而非挂在某次 Placement 上；
7	// 位置/大小/角度/层级（x/y/scale/rotation/z）才随「这次摆放」走。
8	
9	/** 场景 = 一个画布（房间空间），绑定一张预置背景图。背景不可重复，上限 3。 */
10	export interface Scene {
11	  id: string;
12	  name: string;
13	  /** 关联内置背景素材的 id（见 assets/manifest 的 BACKGROUNDS） */
14	  backgroundId: string;
15	}
16	
17	/** 物件 = 想陈列的旧物，带一段用户写的故事（故事挂物件本身，跨场景同步）。 */
18	export interface Item {
19	  id: string;
20	  name: string;
21	  /** 透明抠图的图片地址（构建后为打包资源 URL） */
22	  imageSrc: string;
23	  /** 用户写的故事；初始为空串 */
24	  story: string;
25	}
26	
27	/**
28	 * 摆放 = 某个 Item 在某个 Scene 中的一次落位（多对多的连接实体）。
29	 *
30	 * N2（schema v3）：坐标系锚定「场景图坐标系」——即 contain 居中后场景图占据的那块矩形（imgRect），
31	 * 而非整块可视区。x/y 存物件**中心**在图内的百分比、w 存物件**宽度**占图宽的百分比：
32	 *   x = 中心水平位置 / 图宽 × 100，y = 中心垂直位置 / 图高 × 100，w = 物件宽 / 图宽 × 100。
33	 * 由此窗口任意缩放时，物件位置与大小都随场景图一起重排——钉在房间同一相对位置与相对大小。
34	 * 常规摆放落在 0–100；允许坐标出界（<0 或 >100）把物件摆进两侧的模糊补边区。
35	 * 物件高度由 w 与该物件素材的真实宽高比（ItemAsset.aspectRatio）导出，不单独存储。
36	 *
37	 * 变更史：v1 像素位移 → v2 可视区百分比 + scale 倍率 → v3 场景图坐标系百分比 x/y/w（本次）。
38	 * 旧版数据不迁移、直接作废重置（见 storage/persistence）。
39	 */
40	export interface Placement {
41	  id: string;
42	  sceneId: string;
43	  itemId: string;
44	  /** 物件中心的水平位置：场景图坐标系内百分比（相对图宽；0=左缘,100=右缘；可出界进补边区） */
45	  x: number;
46	  /** 物件中心的垂直位置：场景图坐标系内百分比（相对图高；0=上缘,100=下缘；可出界进补边区） */
47	  y: number;
48	  /** 物件宽度：占场景图宽的百分比（随图缩放，钉在房间同一相对大小；高度由素材宽高比导出） */
49	  w: number;
50	  /** 旋转角度（deg） */
51	  rotation: number;
52	  /** 层级（同场景内的堆叠顺序，越大越靠上） */
53	  z: number;
54	}
55	
56	/** 编辑 / 游客 双模式。 */
57	export type Mode = 'edit' | 'guest';
58	
59	/**
60	 * 全量应用状态 —— LocalStorage 全量读写的单一载体（非增量）。
61	 * schemaVersion 用于持久化格式版本管理与后续迁移。
62	 */
63	export interface GalleryState {
64	  schemaVersion: number;
65	  /** 陈列室名（品牌章）——报头就地编辑，随状态持久化（N3·管理与命名）。 */
66	  galleryName: string;
67	  scenes: Scene[];
68	  items: Item[];
69	  placements: Placement[];
70	  /** 当前激活的场景 id；无场景时为 null */
71	  activeSceneId: string | null;
72	  mode: Mode;
73	}
74

