37	  imageSrc: string;
38	  /** 缩略（场景条 / 选择器用）；当前无独立缩略图，复用原图 */
39	  thumbSrc: string;
40	}
41	
42	/** 物件素材清单条目。 */
43	export interface ItemAsset {
44	  id: string;
45	  name: string;
46	  /** 透明抠图原图地址 */
47	  imageSrc: string;
48	  /** 缩略（物件抽屉缩略卡用）；透明抠图本身即可作缩略，复用原图 */
