77	  { id: 'living-5', name: '潮玩公仔', imageSrc: itLiving5, thumbSrc: itLiving5, aspectRatio: 0.6274 },
78	  { id: 'living-6', name: '旧地球仪', imageSrc: itLiving6, thumbSrc: itLiving6, aspectRatio: 0.9058 },
79	  { id: 'living-7', name: '掌上游戏机', imageSrc: itLiving7, thumbSrc: itLiving7, aspectRatio: 0.617 },
80	  { id: 'living-8', name: '一杯咖啡', imageSrc: itLiving8, thumbSrc: itLiving8, aspectRatio: 1.0639 },
81	];
82	
83	/** 场景数量上限 = 内置背景数量（背景不可重复）。 */
84	export const MAX_SCENES = BACKGROUNDS.length;
85	
86	/** 按 id 取背景素材。 */
