1	// 裁剪几何：按 alpha 阈值求「真实不透明像素」的包围盒与四边透明边。
2	//
3	// 核心判定：把 alpha >= ALPHA_SOLID 的像素视为「实体像素」，
4	// 低于该阈值的一律当作透明留白或烘焙软阴影（不计入包围盒）。
5	// 阈值取得较高（见常量说明），因此半透明软阴影、抗锯齿羽化边
6	// 都不会把包围盒撑大——这正是本 sprint 要解决的「阴影撑歪比例、
7	// 选中框比实物大一圈」的问题。
8	
9	// 实体判定阈值：alpha ≥ 此值才算真实不透明像素。
10	// 实测 14 张图（见 receipt）alpha 直方图：实体主体几乎全为 255，
11	// 烘焙软阴影集中在 alpha ≤ ~180 的半透明区间；取 240 可干净剔除
12	// 阴影与羽化边，且不会误伤实体本体。
13	export const ALPHA_SOLID = 240;
14	
15	// 裁剪后四周保留的呼吸边（px）。契约要求四边透明边 ≤8px，
16	// 取 6 既留出抗锯齿羽化边的观感余量，又稳妥地卡在 8 以内。
17	export const BREATH_PAD = 6;
18	
19	// 契约硬指标：裁剪后四边透明边不得超过此值（px）。
20	export const MAX_TRANSPARENT_MARGIN = 8;
21	
22	/**
23	 * 求实体像素包围盒（inclusive）。无任何实体像素时返回 null。
24	 * @param {{width:number,height:number,data:Uint8Array}} img
25	 * @param {number} threshold alpha 阈值
26	 * @returns {{left:number,top:number,right:number,bottom:number}|null}
27	 */
28	export function opaqueBounds(img, threshold = ALPHA_SOLID) {
29	  const { width, height, data } = img;
30	  let left = width, top = height, right = -1, bottom = -1;
31	  for (let y = 0; y < height; y++) {
32	    const row = y * width;
33	    for (let x = 0; x < width; x++) {
34	      const a = data[(row + x) * 4 + 3];
35	      if (a >= threshold) {
36	        if (x < left) left = x;
37	        if (x > right) right = x;
38	        if (y < top) top = y;
39	        if (y > bottom) bottom = y;
40	      }
41	    }
42	  }
43	  if (right < 0) return null;
44	  return { left, top, right, bottom };
45	}
46	
47	/**
48	 * 四边透明边宽度（px）：从各边缘到最近实体像素之间的空白行/列数。
49	 * @returns {{top:number,right:number,bottom:number,left:number}|null}
50	 */
51	export function sideMargins(img, threshold = ALPHA_SOLID) {
52	  const b = opaqueBounds(img, threshold);
53	  if (!b) return null;
54	  return {
55	    top: b.top,
56	    left: b.left,
57	    right: img.width - 1 - b.right,
58	    bottom: img.height - 1 - b.bottom,
59	  };
60	}
61	
62	/**
63	 * 实体宽高比 = 实体包围盒宽 / 高（不含呼吸边）。保留 4 位小数。
64	 */
65	export function entityAspectRatio(img, threshold = ALPHA_SOLID) {
66	  const b = opaqueBounds(img, threshold);
67	  if (!b) return null;
68	  const w = b.right - b.left + 1;
69	  const h = b.bottom - b.top + 1;
70	  return Math.round((w / h) * 10000) / 10000;
71	}
72

