    if (data.length === 0) throw new Error('里程碑清单至少要有一条');
    for (const m of data) {
      mustObject(m, '里程碑条目');
      mustNonEmptyString(m.id, '里程碑的 id');
      mustNonEmptyString(m.goal, `里程碑 ${m.id} 的 goal（可量化目标）`);
      // 定义里程碑那一刻就要明确「需不需要一件可看的 artifact」——留给 claim 时的机器闸判：
      // 声明了 true 而 manifest 里查无 source=milestone/<id> 的条目，申报完成会被拒收。
      if (typeof m.artifact_required !== 'boolean') {
        throw new Error(`里程碑 ${m.id} 必须明确 artifact_required（true/false）：这个里程碑需不需要产出一件老板在 hub 画廊能看的 artifact`);
      }
      mustArray(m.criteria, `里程碑 ${m.id} 的 criteria（验收标准）`);
      if (m.criteria.length === 0) throw new Error(`里程碑 ${m.id} 的 criteria（验收标准）至少要有一条`);
      for (const [i, c] of m.criteria.entries()) {
        mustObject(c, `里程碑 ${m.id} 第 ${i + 1} 条验收标准`);
        mustNonEmptyString(c.desc, `里程碑 ${m.id} 第 ${i + 1} 条验收标准的 desc（白话说明）`);
        const hasCheck = typeof c.check === 'object' && c.check !== null && !Array.isArray(c.check);
        const isManual = c.manual === true;
        if (hasCheck === isManual) {
          throw new Error(`里程碑 ${m.id} 第 ${i + 1} 条验收标准必须在 check（程序可判）和 manual:true（人工判）里恰好选一个`);
        }
        // check.type 现场核对白名单：写坏的类型（拼写错/编造的类型）当场拒收，
        // 不等到验收执行（acceptance.mjs judgeCheck）才炸——白名单与运行期判定共用同一份 SSOT。
        if (hasCheck) {
          if (typeof c.check.type !== 'string' || c.check.type.trim() === '') {
            throw new Error(`里程碑 ${m.id} 第 ${i + 1} 条验收标准的 check.type 必须是非空文字`);
