          if (!MACHINE_CHECK_TYPES.has(c.check.type)) {
            throw new Error(
              `里程碑 ${m.id} 第 ${i + 1} 条验收标准的 check.type「${c.check.type}」不认识，只支持 ${[...MACHINE_CHECK_TYPES].join('、')}`
            );
          }
        }
      }
    }
  }
},
